 comparisonInFlight=true;
 const source=stagedComparison.old,target=stagedComparison.new;
 controller=new AbortController();setBusy(true);setComparisonLoading(true,'Preparing the comparison engine…');$('scan-progress').hidden=false;$('progress-log').replaceChildren();progress('Sending compact source and target evidence to the backend comparison engine…');
