  const sameExtractedSystem=!sameSavedLibrary&&!!finding?.data&&((finding.data.implementationRatio>=.25&&finding.data.tokenRatio>=.25&&finding.data.nameCount>=120)||(finding.data.implementationRatio>=.5&&finding.data.nameCount>=80));
  const compact=profile=>({input:profile.input||{},fingerprint:profile.fingerprint.storageFormat===1?profile.fingerprint:engine.compactFingerprint(structuredClone(profile.fingerprint)),coverage:profile.coverage||null,registry:profile.registry||null,detection:profile.detection||null,derived:profile.derived||null,packages:profile.packages||[],sources:profile.sources||[],previewAssets:profile.previewAssets||{styles:[],runtimes:[],pages:[]},savedSummary:profile.savedSummary||null,placeholders:profile.placeholders||[],extractionProvider:profile.extractionProvider||{requested:'deterministic',used:'deterministic'}});
