  nextReport.previewSystems={old:source.previewAssets,new:target.previewAssets};
  await engine.restoreComparisonReferences(nextReport,{old:source.__hydrated,new:target.__hydrated},async()=>{await comparisonYield();if(controller.signal.aborted)throw new DOMException('Comparison cancelled.','AbortError')});
  report=nextReport;
  await comparisonYield();
