// initStepper attached the legacy handler before this override is evaluated.
// Capture-phase interception keeps that handler from running the comparison
// engine in the browser while preserving the existing button and keyboard UX.
const backendCompareButton=$('run-button');
if(backendCompareButton)backendCompareButton.addEventListener('click',event=>{event.preventDefault();event.stopImmediatePropagation();compareStepperStagesOnServer()},true);
// Extraction inventories are immutable until replaced. Reuse the duplicate
// check performed after extraction rather than rebuilding giant signatures
// again when Compare is pressed.
const duplicateEvidenceCache=new WeakMap(),computeDuplicateEvidence=duplicateEvidence;
duplicateEvidence=(source,target)=>{let targets=duplicateEvidenceCache.get(source);if(!targets){targets=new WeakMap();duplicateEvidenceCache.set(source,targets)}if(!targets.has(target))targets.set(target,computeDuplicateEvidence(source,target));return targets.get(target)};
